(3451665, 482716, 15711, '<td valign="top">Great lighting. I like the glimmer off of the metallic face of the clock. Cute.</td>', 'Great lighting. I like the glimmer off of the metallic face of the clock. Cute.', '2007-03-12 01:05:52.000000', NULL, 1),
(3451702, 482511, 15711, '<td valign="top">That is very cool.  Maybe too esoteric for this bunch, but I love your artful and sincere approach.  It''s truly wonderful.</td>', 'That is very cool.  Maybe too esoteric for this bunch, but I love your artful and sincere approach.  It''s truly wonderful.', '2007-03-12 01:10:10.000000', NULL, 1),
(3451714, 482279, 15711, '<td valign="top">Very cool and artful approach.  Nice contrast!!!</td>', 'Very cool and artful approach.  Nice contrast!!!', '2007-03-12 01:11:50.000000', NULL, 1),
(3451722, 482348, 15711, '<td valign="top">HEE HEE  What a cutie.  Adorable face.  He looks so pleased with himself.  Might''ve been fun to have him holding the baby pic in his lap.</td>', 'HEE HEE  What a cutie.  Adorable face.  He looks so pleased with himself.  Might''ve been fun to have him holding the baby pic in his lap.', '2007-03-12 01:13:01.000000', NULL, 1),
(3451731, 482691, 15711, '<td valign="top">That is REALLY good.  I might have taken off the rings on his hand, but otherwise, GREAT blue tones.  Wonderful DOF.  It doesn''t SCREAM time, but the watch is certainly a tie in.</td>', 'That is REALLY good.  I might have taken off the rings on his hand, but otherwise, GREAT blue tones.  Wonderful DOF.  It doesn''t SCREAM time, but the watch is certainly a tie in.', '2007-03-12 01:14:29.000000', NULL, 1),
(3451743, 482592, 15711, '<td valign="top">I tried to do that and wasn''t successful.  The background doesn''t "match" the foreground if that makes sense.  I''d tone down the vivid blues and orange of the rock a bit.</td>', 'I tried to do that and wasn''t successful.  The background doesn''t "match" the foreground if that makes sense.  I''d tone down the vivid blues and orange of the rock a bit.', '2007-03-12 01:16:14.000000', NULL, 1),
