INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3461503, 482046, 25218, '<td valign="top">Very clever &amp; well done! Just recently I was saying to my wife how I remember the 20th anniversary of the album in 1987 when I was a teenager, and at the time, I thought 20 years was such a long time &amp; that 1967 was ancient history. And now it''s been another 20 years!! It''s weird to think that teenagers today must feel about the 80s how I feel about the 60s.</td>', 'Very clever & well done! Just recently I was saying to my wife how I remember the 20th anniversary of the album in 1987 when I was a teenager, and at the time, I thought 20 years was such a long time & that 1967 was ancient history. And now it''s been another 20 years!! It''s weird to think that teenagers today must feel about the 80s how I feel about the 60s.', '2007-03-14 16:27:09.000000', NULL, 1),
(3461508, 482529, 25218, '<td valign="top">You''ve captured nice textures.</td>', 'You''ve captured nice textures.', '2007-03-14 16:28:02.000000', NULL, 1),
(3461523, 482498, 25218, '<td valign="top">I really, really like this - it''s dynamic, and it''s compelling, and it''s very well done!</td>', 'I really, really like this - it''s dynamic, and it''s compelling, and it''s very well done!', '2007-03-14 16:31:28.000000', NULL, 1),
(3461528, 482498, 30982, '<td valign="top">There''s an incredible sense of urgency and desperation here - while Time may not seem apparent to some, I think this is a wonderful embodiment of the way time can be both fleeting and frozen simultaneously.</td>', 'There''s an incredible sense of urgency and desperation here - while Time may not seem apparent to some, I think this is a wonderful embodiment of the way time can be both fleeting and frozen simultaneously.', '2007-03-14 16:32:46.000000', NULL, 1),
(3461532, 482678, 30982, '<td valign="top">While some may fault technicals on this, I think the poignancy makes this a tremendous shot.  Maybe a little sad, but mostly contemplative as your title suggests.  A tribute to what has been and what''s to come.  Very well done.</td>', 'While some may fault technicals on this, I think the poignancy makes this a tremendous shot.  Maybe a little sad, but mostly contemplative as your title suggests.  A tribute to what has been and what''s to come.  Very well done.', '2007-03-14 16:33:51.000000', NULL, 1),
(3461540, 482848, 30982, '<td valign="top">Something both haunting and driven about this.  I like it.</td>', 'Something both haunting and driven about this.  I like it.', '2007-03-14 16:34:55.000000', NULL, 1),
(3461542, 482178, 30982, '<td valign="top">Very nicely presented - the colors work, the motion works, and having the clock as the centerpiece ties it all together.</td>', 'Very nicely presented - the colors work, the motion works, and having the clock as the centerpiece ties it all together.', '2007-03-14 16:35:24.000000', NULL, 1),
(3461545, 482425, 30982, '<td valign="top">Mystical and magical - very much works for me.</td>', 'Mystical and magical - very much works for me.', '2007-03-14 16:35:39.000000', NULL, 1),
(3461546, 482113, 30982, '<td valign="top">Clever and well executed.</td>', 'Clever and well executed.', '2007-03-14 16:35:53.000000', NULL, 1),
(3461549, 482528, 30982, '<td valign="top">I love the richness and shapes/lines/curves.  Feels warm and thoughtful.</td>', 'I love the richness and shapes/lines/curves.  Feels warm and thoughtful.', '2007-03-14 16:36:43.000000', NULL, 1),
(3461555, 482436, 30982, '<td valign="top">Beautiful tribute and truly underscores the limits of time.</td>', 'Beautiful tribute and truly underscores the limits of time.', '2007-03-14 16:37:24.000000', NULL, 1),
(3461557, 482433, 30982, '<td valign="top">An absolutely lovely portrait.</td>', 'An absolutely lovely portrait.', '2007-03-14 16:37:40.000000', NULL, 1),
(3461558, 482846, 30982, '<td valign="top">Wonderful perspective, framing, toning.  And simply a lovely image to behold.  Nice work.</td>', 'Wonderful perspective, framing, toning.  And simply a lovely image to behold.  Nice work.', '2007-03-14 16:38:25.000000', NULL, 1),
(3461560, 482724, 30982, '<td valign="top">Could be an ad in a magazine.</td>', 'Could be an ad in a magazine.', '2007-03-14 16:38:40.000000', NULL, 1),
(3461562, 482160, 30982, '<td valign="top">Not sure that this conveys the theme well but it sure is a fun picture!</td>', 'Not sure that this conveys the theme well but it sure is a fun picture!', '2007-03-14 16:38:58.000000', NULL, 1),
(3461566, 482786, 30982, '<td valign="top">Perhaps not a direct representation of time, but a nice shot just the same.</td>', 'Perhaps not a direct representation of time, but a nice shot just the same.', '2007-03-14 16:39:47.000000', NULL, 1),
(3461571, 482388, 30982, '<td valign="top">Credit for the title.  One can also infer that the taking a picture is a moment in time thing, too.  I really like the perspective and the toning, but mostly I like the quietness of these two enjoying the hustle of the city on what looks to be a wonderful spring day.</td>', 'Credit for the title.  One can also infer that the taking a picture is a moment in time thing, too.  I really like the perspective and the toning, but mostly I like the quietness of these two enjoying the hustle of the city on what looks to be a wonderful spring day.', '2007-03-14 16:42:14.000000', NULL, 1),
(3461715, 482161, 66353, '<td valign="top">The one in Crossdress is better :)</td>', 'The one in Crossdress is better :)', '2007-03-14 17:38:04.000000', NULL, 1),
(3461997, 482113, 71697, '<td valign="top">I love the creative idea of this one!</td>', 'I love the creative idea of this one!', '2007-03-14 19:41:24.000000', NULL, 1),
