(3472183, 482449, 30049, '<td valign="top">Wow!  Top 10 (8th to be exact!) :D  Congrats!<br/> <br/>Seems that many commented on the ''haloing'', myself included, but it certainly didn''t hurt your score very much.  Being a PSP user also, I have a better idea of how you obtained the end result.<br/> <br/>Well done!</td>', 'Wow!  Top 10 (8th to be exact!) :D  Congrats! Seems that many commented on the ''haloing'', myself included, but it certainly didn''t hurt your score very much.  Being a PSP user also, I have a better idea of how you obtained the end result. Well done!', '2007-03-19 10:54:57.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3472188, 482768, 70661, '<td valign="top">Love the BG color with the color of the clock face but like Bob said, maybe if the whole clock was included it would have made a improvement.</td>', 'Love the BG color with the color of the clock face but like Bob said, maybe if the whole clock was included it would have made a improvement.', '2007-03-19 10:56:37.000000', NULL, 0),
(3472202, 482174, 30049, '<td valign="top">Johannes - This is an interesting image and I like the end result overall.  Just food for thought...there''s a slight chance you could have some trouble trying to get an image validated using the techniques as described.  The thinking in prior circumstances is that an element has been added that didn''t exist in the original capture.  Best of luck to you in future challenges.</td>', 'Johannes - This is an interesting image and I like the end result overall.  Just food for thought...there''s a slight chance you could have some trouble trying to get an image validated using the techniques as described.  The thinking in prior circumstances is that an element has been added that didn''t exist in the original capture.  Best of luck to you in future challenges.', '2007-03-19 11:02:29.000000', NULL, 0),
(3472207, 482511, 70661, '<td valign="top">Beautiful job. Congrats!</td>', 'Beautiful job. Congrats!', '2007-03-19 11:05:13.000000', NULL, 0),
(3472213, 482279, 70661, '<td valign="top">Awesome! Congrats!</td>', 'Awesome! Congrats!', '2007-03-19 11:07:06.000000', NULL, 0),
(3472228, 482541, 17937, '<td valign="top">Real quick.  Thanks for all the comments but I just wanted to reply and say that it''s suppose to look grainy and dark.  I tried to make the photo look like an old "Bigfoot" type photograph. (if you know what I mean)  The actual photo was not out of focus, dark nor grainy which made it extremely boring.  So I thought this may give it some character.<br/> <br/><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Madukes:</b></div><hr/><i> I am not trying to sound like a nasty person, but this photo is really out of focus, not a very good idea, grainy, and too dark. I only leave this comment because I think you need an opinon on your photo. That is why you joined dpchallenge in the first place? </i></td></tr></table></td>', 'Real quick.  Thanks for all the comments but I just wanted to reply and say that it''s suppose to look grainy and dark.  I tried to make the photo look like an old "Bigfoot" type photograph. (if you know what I mean)  The actual photo was not out of focus, dark nor grainy which made it extremely boring.  So I thought this may give it some character. Originally posted by Madukes: I am not trying to sound like a nasty person, but this photo is really out of focus, not a very good idea, grainy, and too dark. I only leave this comment because I think you need an opinon on your photo. That is why you joined dpchallenge in the first place? ', '2007-03-19 11:11:54.000000', NULL, 0),
(3472229, 482511, 37961, '<td valign="top">Yay.</td>', 'Yay.', '2007-03-19 11:12:23.000000', NULL, 0),
